SELECT 
FROM comments
WHERE article_id = #{articleId}
  AND parent_id = 0

    AND (created_at < #{cursorTime}
         OR (created_at = #{cursorTime} AND id < #{cursorId}))

ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT 
FROM comments
WHERE parent_id = #{rootId}

    AND (created_at > #{cursorTime}
         OR (created_at = #{cursorTime} AND id > #{cursorId}))

ORDER BY created_at ASC, id ASC
LIMIT #{limit}

SELECT * FROM (
    SELECT c.*,
           ROW_NUMBER() OVER (
               PARTITION BY c.parent_id
               ORDER BY c.created_at ASC, c.id ASC
           ) AS rn
    FROM comments c
    WHERE c.parent_id IN

        #{parentId}

) preview
WHERE preview.rn <= #{limit}
ORDER BY preview.parent_id ASC, preview.created_at ASC, preview.id ASC

SELECT parent_id AS parent_id, COUNT(*) AS reply_count FROM comments WHERE parent_id IN
#{parentId}
GROUP BY parent_id

mapper.update:
UPDATE comments
SET deleted = 1,
    updated_at = #{updatedAt}
WHERE id = #{id}
